export const GLOSSARY = [
  { num: 1, term: "Algoritmo", def: "Conjunto ordenado de pasos lógicos y finitos para resolver un problema o realizar una tarea.", example: "El algoritmo de ordenación por mezcla (Merge Sort).", uso: "Base del diseño de software para optimizar cálculo y procesamiento masivo de datos." },
  { num: 2, term: "API (Application Programming Interface)", def: "Conjunto de reglas y especificaciones que permite que diferentes aplicaciones se comuniquen e intercambien datos entre sí.", example: "La API de Stripe.", uso: "Construcción de arquitecturas desacopladas (REST, GraphQL, gRPC)." },
  { num: 3, term: "Aplicación (App)", def: "Programa informático diseñado para realizar tareas específicas directamente para el usuario u otro sistema.", example: "Una aplicación móvil de banca.", uso: "Empaquetado e instalación en plataformas objetivo." },
  { num: 4, term: "Backend", def: "Capa del software que se ejecuta en el servidor y gestiona la lógica de negocio, bases de datos, seguridad y autenticación.", example: "Un servidor FastAPI en Python.", uso: "Implementación de pipelines de procesamiento." },
  { num: 5, term: "Base de datos", def: "Sistema estructurado que almacena, organiza y gestiona información para su consulta y manipulación eficiente.", example: "Una base de datos PostgreSQL.", uso: "Garantizar propiedades ACID." },
  { num: 6, term: "Bug", def: "Error, defecto o fallo no intencionado en el código que produce un comportamiento erróneo o inesperado.", example: "Un error de índice fuera de rango.", uso: "Identificación mediante depuradores y suites de pruebas." },
  { num: 7, term: "Código fuente", def: "Texto legible por humanos escrito por programadores utilizando la sintaxis de un lenguaje de programación.", example: "Las líneas de código en un archivo main.py o App.tsx.", uso: "Sujeto a control de versiones y análisis estático." },
  { num: 8, term: "Código objeto", def: "Código resultante del proceso de compilación, compuesto por instrucciones en lenguaje máquina o bytecode intermedio.", example: "Un archivo binario .o generado por GCC.", uso: "Entrada directa para el enlazador (linker)." },
  { num: 9, term: "Compilador", def: "Programa que traduce código fuente escrito en un lenguaje de alto nivel a código máquina o binario ejecutable.", example: "g++ traduce código C++ a binarios nativos.", uso: "Realiza análisis léxico, sintáctico y semántico." },
  { num: 10, term: "Constante", def: "Identificador cuyo valor asignado no puede modificarse durante la ejecución del programa.", example: "const MAX_CONNECTIONS = 100.", uso: "Prevención de efectos secundarios." },
  { num: 11, term: "Contenedor (Container)", def: "Paquete ligero y ejecutable que contiene una aplicación junto con todas sus dependencias, librerías y configuración.", example: "Un contenedor Docker ejecutando una app Node.js.", uso: "Estandarización de entornos para despliegues reproducibles." },
  { num: 12, term: "Deploy (Despliegue)", def: "Proceso mediante el cual una versión de software se transfiere y se pone en funcionamiento en un entorno de ejecución.", example: "Publicar una nueva versión de una API en AWS.", uso: "Ejecución automatizada mediante pipelines CI/CD." },
  { num: 13, term: "Desarrollo de aplicaciones", def: "Proceso estructurado de recolección de requerimientos, diseño, codificación, pruebas y puesta en producción de software funcional.", example: "Crear una app de entrega de comida a domicilio.", uso: "Aplicación de metodologías ágiles." },
  { num: 14, term: "Desarrollo de software", def: "Disciplina que engloba todas las actividades técnicas, metodológicas y de ingeniería para concebir, construir y evolucionar sistemas informáticos.", example: "Construcción de un sistema distribuido.", uso: "Gestión de deuda técnica." },
  { num: 15, term: "Documentación", def: "Conjunto de textos, especificaciones, diagramas y comentarios que describen la arquitectura, APIs y uso de un software.", example: "Una especificación OpenAPI/Swagger.", uso: "Mantenibilidad del proyecto." },
  { num: 16, term: "Entorno de desarrollo (IDE)", def: "Aplicación de software que proporciona herramientas integradas como editor de código, depurador, terminal y compilador.", example: "Visual Studio Code, IntelliJ IDEA o PyCharm.", uso: "Incremento de productividad." },
  { num: 17, term: "Framework", def: "Estructura conceptual y tecnológica que provee un esqueleto estándar y reutilizable con inversión de control para construir aplicaciones.", example: "Django en Python, Spring Boot en Java.", uso: "Estandarización arquitectónica." },
  { num: 18, term: "Frontend", def: "Capa del software orientada a la presentación e interacción directa con el usuario final en navegadores o interfaces nativas.", example: "La interfaz interactiva construida en React con Tailwind CSS.", uso: "Manipulación del DOM, gestión reactiva del estado." },
  { num: 19, term: "Función", def: "Bloque estructurado de código con nombre que recibe parámetros, ejecuta una serie de instrucciones y opcionalmente retorna un resultado.", example: "def calcular_descuento(precio, porcentaje).", uso: "Modularización y reutilización bajo el principio DRY." },
  { num: 20, term: "Git", def: "Sistema de control de versiones distribuido diseñado para rastrear cambios en el código fuente de proyectos de software.", example: "git commit -m \"Fix: corregir validación de email\".", uso: "Gestión colaborativa de ramas." },
  { num: 21, term: "Hardware", def: "Componentes físicos, electrónicos y mecánicos que integran un ordenador o dispositivo informático.", example: "Microprocesador CPU multi-núcleo, módulos de memoria RAM DDR5.", uso: "Asignación de recursos mediante capas de abstracción." },
  { num: 22, term: "Interfaz de usuario (UI)", def: "Conjunto de controles visuales, pantallas y elementos gráficos que permiten la interacción humana con una aplicación.", example: "Botones, modales, barras de navegación.", uso: "Implementación de sistemas de diseño." },
  { num: 23, term: "Lenguaje de programación", def: "Sistema formal con reglas sintácticas y semánticas precisas para formular instrucciones ejecutables por una computadora.", example: "Rust, Go, TypeScript, Python o C++.", uso: "Selección técnica según necesidades de gestión de memoria." },
  { num: 24, term: "Librería (Library)", def: "Colección organizada de funciones, clases y recursos reutilizables que una aplicación importa para resolver tareas concretas.", example: "Axios para peticiones HTTP.", uso: "Delegación de tareas especializadas." },
  { num: 25, term: "Método", def: "Función declarada dentro del contexto de una clase o estructura que opera sobre los datos del objeto asociado.", example: "cuenta.transferir(monto, cuenta_destino).", uso: "Encapsulamiento del comportamiento." },
  { num: 26, term: "Módulo", def: "Archivo o unidad de código independiente que agrupa funciones, tipos y constantes relacionadas para su exportación e importación.", example: "import math en Python.", uso: "Desacoplamiento funcional." },
  { num: 27, term: "Parámetro", def: "Variable declarada en la firma de una función que actúa como receptor de los valores (argumentos) pasados al invocarla.", example: "function enviarEmail(destinatario, asunto).", uso: "Definición de contratos de entrada." },
  { num: 28, term: "Programa", def: "Secuencia completa de instrucciones ejecutables por una computadora para cumplir un objetivo o proceso automático.", example: "Un script en Python que procesa archivos CSV.", uso: "Carga en memoria y ejecución." },
  { num: 29, term: "Programación orientada a objetos (POO)", def: "Paradigma de programación basado en la organización del código en clases y objetos que combinan estado y comportamiento.", example: "Clases Vehiculo, Coche y Camion con herencia.", uso: "Diseño de sistemas desacoplados." },
  { num: 30, term: "Prototipo", def: "Modelo preliminar o interactivo de un producto de software creado para validar requisitos, flujos y arquitectura.", example: "Un prototipo interactivo en Figma.", uso: "Validación temprana de usabilidad." },
  { num: 31, term: "Pruebas (Testing)", def: "Proceso sistemático de evaluación del software para verificar que cumple los requerimientos y detectar fallos antes de producción.", example: "Ejecutar suites con pytest.", uso: "Implementación en pipelines de integración continua." },
  { num: 32, term: "QA (Quality Assurance)", def: "Disciplina y conjunto de actividades orientadas a garantizar que los procesos y productos de software alcancen los estándares de calidad.", example: "Un ingeniero QA diseñando planes de pruebas.", uso: "Automatización de pruebas end-to-end." },
  { num: 33, term: "Refactorización (Refactoring)", def: "Reestructuración interna del código fuente sin alterar su comportamiento externo observable.", example: "Dividir una función monolítica de 300 líneas en cuatro funciones cohesivas.", uso: "Reducción de deuda técnica." },
  { num: 34, term: "Repositorio", def: "Estructura de almacenamiento centralizada o distribuida donde se guarda el código fuente, archivos y su historial de versiones.", example: "Un repositorio alojado en GitHub.", uso: "Base del control de versiones distribuido." },
  { num: 35, term: "Script", def: "Archivo de texto plano con instrucciones ejecutadas directamente por un intérprete para automatizar tareas.", example: "Un script en Bash que comprime una base de datos y la sube a AWS S3.", uso: "Automatización de despliegues." },
  { num: 36, term: "Servidor", def: "Sistema informático (hardware y software) que atiende peticiones de red y proporciona recursos o servicios a clientes.", example: "Un servidor Nginx que escucha en el puerto 443.", uso: "Configuración de alta disponibilidad." },
  { num: 37, term: "Sintaxis", def: "Conjunto de reglas formales que establecen cómo deben combinarse símbolos y palabras clave para formar instrucciones válidas.", example: "En Python los bloques se delimitan por indentación.", uso: "Análisis léxico y gramatical." },
  { num: 38, term: "Software", def: "Conjunto intangible de programas, procedimientos, reglas y documentación asociados a la operación de un sistema de cómputo.", example: "El sistema operativo Linux, un navegador web.", uso: "Construcción modular." },
  { num: 39, term: "Variable", def: "Espacio en memoria con un identificador asociado que almacena un dato susceptible de cambiar durante la ejecución.", example: "let contador = 0; contador += 1.", uso: "Asignación en stack o heap." },
  { num: 40, term: "Versión", def: "Estado específico y numerado en la evolución de un software a lo largo del tiempo.", example: "v2.4.1 siguiendo el estándar SemVer.", uso: "Gestión de compatibilidad de dependencias." },
  { num: 41, term: "Wireframe", def: "Esquema visual esquemático y de baja fidelidad que representa la disposición estructural y navegación de una interfaz.", example: "Un boceto en blanco y negro de la barra de búsqueda.", uso: "Alineación entre diseño de producto y desarrolladores." },
  { num: 42, term: "Workflow", def: "Secuencia automatizada u organizada de pasos y condiciones para completar un proceso de negocio o desarrollo.", example: "Solicitud → Revisión → Validación → Pago automático.", uso: "Modelado mediante máquinas de estados finitos." },
  { num: 43, term: "Algoritmo de ordenación", def: "Algoritmo computacional diseñado para reorganizar elementos de una colección en un orden secuencial específico.", example: "QuickSort con complejidad promedio O(n log n).", uso: "Optimización de búsquedas binarias." },
  { num: 44, term: "Arquitectura de software", def: "Estructura de alto nivel que define los componentes principales de un sistema, sus relaciones y las directrices de diseño.", example: "Arquitectura hexagonal (Ports & Adapters).", uso: "Garantizar atributos de calidad." },
  { num: 45, term: "Backlog", def: "Lista priorizada y dinámica de historias de usuario, tareas, mejoras y correcciones pendientes de ejecución en un proyecto.", example: "Un backlog en Jira priorizado con 15 historias de usuario.", uso: "Gestión del alcance en marcos ágiles." },
  { num: 46, term: "Big Data", def: "Conjuntos masivos y heterogéneos de datos cuyo volumen, velocidad y variedad superan la capacidad de las herramientas tradicionales.", example: "Procesamiento en streaming de miles de millones de eventos IoT.", uso: "Uso de arquitecturas distribuidas como Apache Spark." },
  { num: 47, term: "Cloud Computing", def: "Modelo de suministro de recursos informáticos bajo demanda (servidores, almacenamiento, redes y software) a través de Internet.", example: "Aprovisionar una base de datos administrada en Amazon RDS.", uso: "Reducción de costos de infraestructura." },
  { num: 48, term: "Control de versiones", def: "Práctica y herramientas para registrar, auditar y gestionar los cambios realizados en el código fuente a lo largo del tiempo.", example: "Utilizar Git para ramificar el desarrollo de una nueva funcionalidad.", uso: "Trazabilidad de autoría." },
  { num: 49, term: "Debugging (Depuración)", def: "Proceso metódico de rastreo, aislamiento y corrección de defectos o comportamientos anómalos en el código fuente.", example: "Establecer puntos de interrupción (breakpoints) con un depurador.", uso: "Análisis de stack traces." },
  { num: 50, term: "DevOps", def: "Cultura, conjunto de prácticas y herramientas que integran el desarrollo de software (Dev) con las operaciones de TI (Ops).", example: "Un pipeline unificado con Terraform y GitHub Actions.", uso: "Reducción del ciclo de vida del desarrollo." },
  { num: 51, term: "Endpoint", def: "URL o ruta específica expuesta por un servidor API para recibir solicitudes y ejecutar operaciones concretas.", example: "POST /api/v1/auth/login.", uso: "Definición de contratos en OpenAPI." },
  { num: 52, term: "Entorno de ejecución (Runtime)", def: "Entorno de software que provee los recursos, bibliotecas y máquina de estados necesarios para ejecutar un programa.", example: "Node.js o la JVM.", uso: "Gestión de la memoria y recolección de basura." },
  { num: 53, term: "Error de sintaxis", def: "Infracción de las reglas gramaticales del lenguaje que impide al analizador compilar o interpretar el código.", example: "Olvidar cerrar una llave en C++.", uso: "Detección en tiempo de análisis estático por linters." },
  { num: 54, term: "Error lógico", def: "Defecto en el diseño o implementación del algoritmo que hace que el programa funcione sin fallar pero produzca resultados incorrectos.", example: "Usar total = precio * impuesto en lugar de total = precio + (precio * impuesto).", uso: "Requiere pruebas unitarias exhaustivas." },
  { num: 55, term: "Excepción", def: "Suceso anómalo o inesperado que altera el flujo normal de ejecución de un programa en tiempo de ejecución.", example: "FileNotFoundException.", uso: "Manejo controlado con bloques try/catch/finally." },
  { num: 56, term: "Expresión", def: "Unidad de código compuesta por valores, constantes, variables y operadores que el evaluador resuelve a un único valor.", example: "(a + b) > 10 && activo === true.", uso: "Elemento fundamental en sentencias condicionales." },
  { num: 57, term: "Flujo de control", def: "Orden secuencial y condicional en el que se ejecutan las sentencias e instrucciones de un programa.", example: "Un bloque if-else que bifurca el procesamiento.", uso: "Estructuras condicionales, iterativas y manejo de saltos." },
  { num: 58, term: "Full stack", def: "Perfil o arquitectura de desarrollo que abarca tanto las tecnologías del cliente (frontend) como las del servidor (backend y bases de datos).", example: "UI en Next.js, API en Node.js y base de datos en MongoDB.", uso: "Visión integral del ciclo de vida de la petición." },
  { num: 59, term: "Función recursiva", def: "Función que se invoca a sí misma para descomponer un problema en subproblemas más pequeños hasta alcanzar un caso base.", example: "Recorrer la estructura en árbol de un sistema de directorios.", uso: "Procesamiento de estructuras no lineales." },
  { num: 60, term: "Hardcoding", def: "Práctica de incrustar valores fijos o datos de configuración directamente en el código fuente en lugar de cargarlos dinámicamente.", example: "const DB_HOST = \"192.168.1.50\".", uso: "Considerado un antipatrón en producción." },
  { num: 61, term: "Herencia (en POO)", def: "Mecanismo que permite a una clase derivada adquirir atributos y métodos de una clase base.", example: "EmpleadoPorHoras hereda de Empleado.", uso: "Establecimiento de jerarquías de tipos." },
  { num: 62, term: "Hook (gancho)", def: "Punto de intercepción en un framework que permite inyectar lógica personalizada durante el ciclo de vida de un componente o proceso.", example: "useEffect en React.", uso: "Extensibilidad modular." },
  { num: 63, term: "HTTP", def: "Protocolo de capa de aplicación sin estado que define las reglas para la transferencia de recursos en la World Wide Web.", example: "GET /index.html HTTP/1.1.", uso: "Base de la comunicación web moderna." },
  { num: 64, term: "IDE (Integrated Development Environment)", def: "Software que integra editor de texto enriquecido, compilador/intérprete, depurador y herramientas de automatización.", example: "Android Studio.", uso: "Centralización del flujo de trabajo de desarrollo." },
  { num: 65, term: "Implementación", def: "Realización práctica y escritura del código fuente que da cumplimiento a un diseño arquitectónico o interfaz.", example: "Escribir la clase StripePaymentGateway.", uso: "Transformación de requisitos en componentes operativos." },
  { num: 66, term: "Instancia", def: "Objeto concreto y único creado en memoria a partir del molde definido por una clase.", example: "const usuario1 = new Usuario(\"Carlos\", \"carlos@mail.com\").", uso: "Ocupa espacio específico en el heap." },
  { num: 67, term: "Integración continua (CI)", def: "Práctica donde los miembros del equipo integran su código frecuentemente, disparando compilaciones y pruebas automáticas.", example: "Un pipeline de GitHub Actions.", uso: "Detección temprana de incompatibilidades." },
  { num: 68, term: "Interfaz (en POO)", def: "Contrato abstracto que define un conjunto de firmas de métodos que una clase debe implementar obligatoriamente.", example: "La interfaz Repositorio<T>.", uso: "Desacoplamiento arquitectónico." },
  { num: 69, term: "Iteración", def: "Cada repetición de un conjunto de instrucciones dentro de un bucle, o cada ciclo de desarrollo de tiempo fijo (sprint).", example: "La quinta pasada por un bucle for.", uso: "Procesamiento secuencial de estructuras iterables." },
  { num: 70, term: "JSON (JavaScript Object Notation)", def: "Formato ligero y de texto plano basado en pares clave-valor y arrays para el intercambio estructurado de datos.", example: "{\"id\": 101, \"nombre\": \"Teclado Mecánico\", \"precio\": 89.99}.", uso: "Estándar universal para APIs REST." },
  { num: 71, term: "Lenguaje interpretado", def: "Lenguaje cuyas instrucciones son leídas, analizadas y ejecutadas directamente en tiempo de ejecución por un intérprete.", example: "Python o JavaScript.", uso: "Prototipado rápido y flexibilidad." },
  { num: 72, term: "Lenguaje compilado", def: "Lenguaje cuyo código fuente se traduce por completo a código máquina nativo antes de su ejecución.", example: "Rust, Go o C++.", uso: "Máximo rendimiento en tiempo de ejecución." },
  { num: 73, term: "Lógica de negocio", def: "Reglas, algoritmos y flujos de trabajo específicos que determinan cómo se crean, validan y modifican los datos en el dominio de una empresa.", example: "15% de descuento si la compra supera 100€.", uso: "Aislamiento en capas de dominio." },
  { num: 74, term: "Loop (bucle)", def: "Estructura de control que repite la ejecución de un bloque de código mientras se cumpla una condición lógica.", example: "while (conexionActiva) { procesarMensaje(); }.", uso: "Iteración sobre estructuras de datos." },
  { num: 75, term: "Mantenimiento de software", def: "Conjunto de modificaciones y optimizaciones realizadas en una aplicación tras su entrega inicial.", example: "Actualizar una dependencia vulnerable.", uso: "Minimizar el coste acumulativo de la deuda técnica." },
  { num: 76, term: "Microservicios", def: "Estilo arquitectónico que estructura una aplicación como una colección de servicios autónomos, pequeños y débilmente acoplados.", example: "Servicios de facturación, catálogo y autenticación comunicados vía gRPC.", uso: "Escalabilidad horizontal independiente." },
  { num: 77, term: "MVC (Model-View-Controller)", def: "Patrón de arquitectura que separa la aplicación en Modelo, Vista y Controlador.", example: "Ruby on Rails o ASP.NET MVC.", uso: "Separación estricta de responsabilidades." },
  { num: 78, term: "Objeto", def: "Entidad encapsulada en memoria que combina estado (propiedades) y comportamiento (métodos).", example: "Un objeto pedido con items, total y procesarPago().", uso: "Unidad central de la POO." },
  { num: 79, term: "Operador", def: "Símbolo o palabra clave que instruye al compilador a realizar una operación matemática, lógica, relacional o de asignación.", example: "+, -, *, ===, &&, ||.", uso: "Sujeto a reglas de precedencia." },
  { num: 80, term: "Optimización", def: "Proceso sistemático de modificación del software para que ejecute más rápido, consuma menos memoria o use menos ancho de banda.", example: "Reemplazar un algoritmo O(n²) por O(n).", uso: "Guiada por métricas obtenidas mediante profiling." },
  { num: 81, term: "Paquete (Package)", def: "Colección distribuible y versionada de módulos, código y metadatos empaquetada para su fácil instalación e integración.", example: "lodash en npm o requests en PyPI.", uso: "Gestión de dependencias automatizada." },
  { num: 82, term: "Patrón de diseño", def: "Solución general, reutilizable y probada para un problema recurrente en el diseño y arquitectura de software.", example: "El patrón Factory Method.", uso: "Estandarización de arquitecturas." },
  { num: 83, term: "Pipeline de datos", def: "Secuencia automatizada de procesos donde la salida de cada etapa sirve como entrada para la siguiente.", example: "Extracción de logs → enriquecimiento → carga en Data Warehouse.", uso: "Implementación con Kafka, Flink o Airflow." },
  { num: 84, term: "Polimorfismo", def: "Capacidad de objetos de diferentes clases de responder a un mismo método con implementaciones distintas.", example: "figura.calcularArea() sobre Circulo y Rectangulo.", uso: "Desacoplamiento de consumidores." },
  { num: 85, term: "Producción (entorno)", def: "Entorno operativo final donde el software está desplegado y accesible para los usuarios finales.", example: "Clústeres de servidores que procesan transacciones de un banco.", uso: "Configuración de alta seguridad." },
  { num: 86, term: "Protocolo", def: "Conjunto estandarizado de reglas y convenciones que rigen el intercambio de datos entre dispositivos de red.", example: "TCP asegurando la entrega ordenada de paquetes.", uso: "Definición en estándares RFC." },
  { num: 87, term: "Pruebas unitarias", def: "Pruebas automatizadas de bajo nivel para validar el comportamiento de unidades individuales y aisladas de código.", example: "Un test con Jest que verifica que sumar(2, 3) retorna 5.", uso: "Ejecución rápida en local y CI." },
  { num: 88, term: "Pruebas de integración", def: "Pruebas que validan la correcta interacción y flujo de datos entre dos o más módulos o servicios.", example: "Probar que el servicio de autenticación guarda sesiones en Redis.", uso: "Detección de fallos en contratos de interfaces." },
  { num: 89, term: "Pruebas de aceptación", def: "Pruebas formales que verifican que el sistema satisface los criterios definidos por el cliente o negocio.", example: "Pruebas automatizadas en formato BDD usando Cucumber.", uso: "Condición final para aprobar el pase a producción." },
  { num: 90, term: "Query (consulta)", def: "Solicitud formal de información enviada a una base de datos o motor de búsqueda para recuperar o manipular datos.", example: "SELECT id, nombre FROM clientes WHERE pais = 'ES'.", uso: "Optimización mediante planes de ejecución." },
  { num: 91, term: "Refactorización", def: "Proceso sistemático de reestructurar el código existente sin alterar su funcionalidad externa.", example: "Reemplazar condicionales anidados por el patrón Strategy.", uso: "Se ejecuta con el respaldo de pruebas automatizadas." },
  { num: 92, term: "Renderizado", def: "Proceso de transformar datos abstractos, código y estilos en una representación gráfica visual en pantalla.", example: "El motor del navegador procesando HTML, CSS y JavaScript.", uso: "Estrategias SSR, CSR, SSG." },
  { num: 93, term: "Requerimientos (requirements)", def: "Condiciones y restricciones que debe satisfacer un sistema de software para resolver un problema de negocio.", example: "\"El sistema debe emitir facturas en PDF\".", uso: "Base para la arquitectura del sistema." },
  { num: 94, term: "REST (Representational State Transfer)", def: "Estilo arquitectónico para sistemas distribuidos basado en la manipulación sin estado de recursos mediante URIs.", example: "DELETE /api/usuarios/45.", uso: "Aprovechamiento semántico del protocolo HTTP." },
  { num: 95, term: "Rollback", def: "Operación de reversión que devuelve el estado del sistema a una versión anterior estable tras un fallo.", example: "Revertir un despliegue en Kubernetes.", uso: "Implementación en transacciones SQL y pipelines CI/CD." },
  { num: 96, term: "Sandbox", def: "Entorno de pruebas seguro, controlado y aislado del sistema de producción donde se puede ejecutar código sin riesgo.", example: "El entorno sandbox de PayPal.", uso: "Prevención de contaminación de datos en producción." },
  { num: 97, term: "Scalability (escalabilidad)", def: "Capacidad de un sistema para incrementar su capacidad de procesamiento al añadirle recursos adicionales.", example: "Una API que pasa de 1.000 a 50.000 peticiones/segundo.", uso: "Escalabilidad vertical y horizontal." },
  { num: 98, term: "SDK (Software Development Kit)", def: "Conjunto integrado de herramientas, librerías y documentación para facilitar la creación de apps en una plataforma específica.", example: "El AWS SDK para Python (boto3).", uso: "Agilización del desarrollo." },
  { num: 99, term: "Servicio web", def: "Aplicación o componente accesible a través de una red que ofrece funciones interoperables mediante estándares web.", example: "Un servicio de cotización de divisas en JSON.", uso: "Integración entre sistemas heterogéneos." },
  { num: 100, term: "Sistema de archivos", def: "Estructura y conjunto de algoritmos que un sistema operativo utiliza para organizar, nombrar y recuperar archivos en un soporte físico.", example: "Ext4 en Linux o NTFS en Windows.", uso: "Gestión de descriptores de archivos." },
  { num: 101, term: "Sistema operativo", def: "Software base principal que administra el hardware del ordenador y proporciona servicios esenciales para las demás aplicaciones.", example: "Ubuntu Server, Windows Server o macOS.", uso: "Gestión de procesos, planificación de CPU." },
  { num: 102, term: "Socket", def: "Punto final de comunicación bidireccional entre dos procesos a través de una red de computadoras.", example: "Un socket TCP escuchando en 127.0.0.1:8080.", uso: "Base fundamental de la pila de red." },
  { num: 103, term: "Software libre", def: "Software que respeta la libertad de los usuarios para ejecutar, copiar, distribuir, estudiar, cambiar y mejorar el programa.", example: "El núcleo Linux bajo licencia GNU GPL.", uso: "Cumplimiento de las 4 libertades esenciales de la FSF." },
  { num: 104, term: "Software de código abierto (open source)", def: "Software cuyo código fuente está disponible públicamente bajo licencias que permiten su uso, modificación y redistribución.", example: "React de Meta o Nginx.", uso: "Aprovechamiento de aportes comunitarios." },
  { num: 105, term: "Stack tecnológico", def: "Combinación integrada de lenguajes, frameworks, bases de datos y herramientas que componen una aplicación completa.", example: "Stack MERN o LAMP.", uso: "Selección estratégica basada en requerimientos de rendimiento." },
  { num: 106, term: "Subrutina", def: "Porción identificada de código dentro de un programa mayor que realiza una tarea específica y puede ser llamada desde múltiples puntos.", example: "Una subrutina en ensamblador que calcula un checksum.", uso: "Concepto precursor de funciones modernas." },
  { num: 107, term: "Sincronización", def: "Coordinación temporal de procesos o hilos concurrentes para asegurar un orden estricto y evitar colisiones sobre recursos compartidos.", example: "Usar un cerrojo (mutex) para proteger el saldo de una cuenta.", uso: "Prevención de condiciones de carrera." },
  { num: 108, term: "Testing automatizado", def: "Ejecución sistemática de suites de pruebas mediante scripts y herramientas sin intervención manual humana.", example: "Un runner que ejecuta 2.000 aserciones unitarias en 15 segundos.", uso: "Integración en pipelines CI/CD." },
  { num: 109, term: "Thread (hilo de ejecución)", def: "Unidad básica y más pequeña de ejecución secuencial asignable a la CPU dentro del contexto de un proceso.", example: "Un hilo en segundo plano que descarga una imagen.", uso: "Los hilos comparten el espacio de memoria del proceso padre." },
  { num: 110, term: "Token", def: "Cadena alfanumérica estructurada que actúa como credencial digital de autorización o unidad léxica mínima.", example: "Un JSON Web Token (JWT).", uso: "Autenticación sin estado (stateless) en microservicios." },
  { num: 111, term: "Tipado estático", def: "Sistema de tipos donde los tipos de datos de las variables se verifican en tiempo de compilación.", example: "int total = 100 en C# o const edad: number = 25 en TypeScript.", uso: "Detección precoz de errores." },
  { num: 112, term: "Tipado dinámico", def: "Sistema de tipos donde las comprobaciones de tipo se realizan en tiempo de ejecución.", example: "En Python x = 10 seguido de x = \"hola\".", uso: "Agilidad en scripting y prototipado rápido." },
  { num: 113, term: "Tipo de dato", def: "Clasificación formal que define la naturaleza de un valor, los límites de lo que puede almacenar y las operaciones posibles.", example: "boolean, integer, float, string, Array, Map.", uso: "Determina la cantidad exacta de bytes reservados en memoria." },
  { num: 114, term: "UI (User Interface)", def: "Superficie de contacto e interacción visual, táctil o auditiva mediante la cual un ser humano opera un sistema de software.", example: "La pantalla de inicio de una app móvil.", uso: "Implementación mediante HTML/CSS, SwiftUI." },
  { num: 115, term: "UX (User Experience)", def: "Disciplina que estudia y diseña la percepción integral, satisfacción, facilidad de uso y eficacia del usuario al interactuar con un producto.", example: "Simplificar un checkout de 10 pasos a 1 clic.", uso: "Guiado por pruebas de usabilidad." },
  { num: 116, term: "Validación", def: "Proceso de comprobación de que los datos de entrada o el estado del sistema se ajustan a las reglas de negocio esperadas.", example: "Validar que una cadena cumpla la expresión regular de un correo electrónico.", uso: "Primera línea de defensa de seguridad." },
  { num: 117, term: "Variable local", def: "Variable declarada dentro del cuerpo de una función cuyo ciclo de vida y visibilidad se limitan a dicho ámbito.", example: "La variable temp dentro de una función de ordenamiento.", uso: "Asignada en el stack de llamadas." },
  { num: 118, term: "Variable global", def: "Variable accesible y mutable desde cualquier parte del código fuente de un programa durante todo su ciclo de vida.", example: "window.innerWidth en el navegador.", uso: "Su uso indiscriminado se considera mala práctica." },
  { num: 119, term: "Versión estable", def: "Edición de un software que ha superado exhaustivas fases de pruebas y se considera madura y lista para entornos de producción.", example: "La versión LTS de Node.js v20.x.", uso: "Utilizada como base de despliegue corporativo." },
  { num: 120, term: "Versión beta", def: "Versión preliminar del software con la mayoría de funcionalidades implementadas, distribuida a usuarios reales para detectar fallos.", example: "Una versión beta pública en TestFlight de Apple.", uso: "Recopilación de telemetría de rendimiento." },
  { num: 121, term: "Versión alpha", def: "Primera versión funcional de un producto de software utilizada internamente por el equipo para pruebas iniciales de concepto.", example: "Una versión alpha donde la interfaz básica funciona pero faltan módulos secundarios.", uso: "Identificación temprana de fallos arquitectónicos." },
  { num: 122, term: "Vista (en MVC)", def: "Componente del patrón MVC responsable de presentar los datos del modelo al usuario en un formato visual.", example: "Una plantilla HTML que renderiza la tabla de facturas.", uso: "Debe carecer de lógica de negocio pesada." },
  { num: 123, term: "Web app (aplicación web)", def: "Aplicación de software interactiva ejecutada en un servidor remoto y accesible a través de cualquier navegador web estándar.", example: "Google Docs, Canva o Trello.", uso: "Construcción mediante Single Page Applications." },
  { num: 124, term: "Webhook", def: "Mecanismo de comunicación basado en eventos donde un servidor notifica a otro enviando una petición HTTP POST automática.", example: "GitHub enviando un webhook a un servidor CI/CD.", uso: "Reemplazo eficiente del sondeo constante." },
  { num: 125, term: "WebSocket", def: "Protocolo que proporciona canales de comunicación dúplex completos y persistentes sobre una única conexión TCP.", example: "Un chat grupal o tablero de cotizaciones en tiempo real.", uso: "Transmisión de tramas con latencia mínima." },
  { num: 126, term: "Workflow de desarrollo", def: "Proceso estructurado que siguen los equipos desde la concepción de una tarea hasta su puesta en producción.", example: "Crear rama → Desarrollar → Pruebas → PR → CI → Despliegue.", uso: "Estandarización de políticas de calidad." },
  { num: 127, term: "XML (eXtensible Markup Language)", def: "Lenguaje de marcado basado en etiquetas jerárquicas para almacenar y transportar datos.", example: "<factura id=\"1024\"><cliente>Empresa SA</cliente></factura>.", uso: "Servicios web SOAP, configuración de proyectos Java." },
  { num: 128, term: "YAML (YAML Ain't Markup Language)", def: "Formato de serialización de datos legible por humanos basado en indentación, utilizado para archivos de configuración.", example: "El archivo docker-compose.yml.", uso: "Estándar dominante para manifiestos de Kubernetes." },
  { num: 129, term: "Zero downtime deployment", def: "Estrategia de despliegue que actualiza una aplicación sin interrumpir el servicio ni generar errores para usuarios activos.", example: "Despliegue Blue-Green donde el tráfico se conmuta del clúster antiguo al nuevo.", uso: "Requiere compatibilidad regresiva en bases de datos." },
  { num: 130, term: "Abstracción", def: "Principio de ingeniería que consiste en ocultar la complejidad interna de un sistema y exponer únicamente una interfaz limpia.", example: "Usar coche.arrancar() sin conocer los detalles del encendido.", uso: "Reducción de la carga cognitiva." },
  { num: 131, term: "Acoplamiento (coupling)", def: "Grado de interdependencia y vinculación directa entre dos o más módulos o clases de un sistema.", example: "Un módulo de facturación que accede a variables privadas del módulo de inventario.", uso: "La buena arquitectura persigue el bajo acoplamiento." },
  { num: 132, term: "Alcance (scope)", def: "Contexto léxico o bloque de código dentro del cual un identificador es visible y accesible.", example: "Una variable declarada con let dentro de un bloque if no puede leerse fuera.", uso: "Prevención de colisiones de nombres." },
  { num: 133, term: "Análisis de requisitos", def: "Fase inicial donde se extraen, analizan, especifican y validan las necesidades y restricciones del sistema.", example: "Entrevistar al departamento contable para definir reglas de retenciones.", uso: "Generación de especificaciones formales." },
  { num: 134, term: "Arquitectura cliente-servidor", def: "Modelo de diseño distribuido que reparte las tareas entre servidores y clientes.", example: "Una app móvil de Spotify solicitando canciones a los servidores.", uso: "Centralización del almacenamiento y lógica." },
  { num: 135, term: "Arquitectura monolítica", def: "Patrón donde todos los módulos, lógica de negocio, acceso a datos y UI están integrados en una única base de código.", example: "Una gran aplicación en Ruby on Rails que maneja compras, inventario y facturación.", uso: "Excelente para arrancar proyectos." },
  { num: 136, term: "Asíncrono", def: "Modelo de ejecución donde una tarea se inicia sin bloquear el hilo principal, permitiendo que otras instrucciones continúen.", example: "Descargar un archivo de 500 MB en segundo plano.", uso: "Implementado mediante promesas, callbacks, async/await." },
  { num: 137, term: "Autenticación", def: "Proceso de verificación criptográfica que comprueba que una entidad o usuario es realmente quien dice ser.", example: "Iniciar sesión con usuario, contraseña y código OTP 2FA.", uso: "Mediante protocolos OpenID Connect, SAML o JWT." },
  { num: 138, term: "Autorización", def: "Proceso de verificación de los permisos de un usuario ya autenticado para acceder a un recurso específico.", example: "Un usuario con rol \"editor\" puede modificar pero no borrar.", uso: "Modelos RBAC o ABAC." },
  { num: 139, term: "Backend as a Service (BaaS)", def: "Modelo de servicio en la nube donde los desarrolladores subcontratan funciones de servidor a una plataforma lista para usar.", example: "Firebase o Supabase.", uso: "Aceleración extrema del desarrollo frontend." },
  { num: 140, term: "Balanceo de carga", def: "Técnica de distribución equitativa del tráfico de red entre un grupo de servidores.", example: "AWS Application Load Balancer.", uso: "Algoritmos Round Robin, Least Connections, IP Hash." },
  { num: 141, term: "Benchmark", def: "Prueba estandarizada y cuantitativa utilizada para medir y comparar el rendimiento relativo de un sistema, algoritmo o base de datos.", example: "Medir transacciones/segundo de PostgreSQL vs MySQL.", uso: "Toma de decisiones arquitectónicas." },
  { num: 142, term: "Big O notation (notación O grande)", def: "Notación matemática que describe la complejidad temporal o espacial de un algoritmo cuando la entrada tiende a infinito.", example: "Búsqueda lineal O(n) vs búsqueda binaria O(log n).", uso: "Seleccionar algoritmos y estructuras de datos óptimos." },
  { num: 143, term: "Build (construcción)", def: "Proceso automatizado que compila, transpila, empaqueta y genera los artefactos ejecutables a partir del código fuente.", example: "Ejecutar vite build.", uso: "Automatizado en pipelines CI." },
  { num: 144, term: "Cache (caché)", def: "Capa de almacenamiento temporal de alta velocidad que guarda copias de datos costosos para acelerar accesos futuros.", example: "Resultados de consultas complejas almacenados en Redis.", uso: "Estrategias Cache-Aside, Write-Through." },
  { num: 145, term: "CI/CD", def: "Combinación de integración continua (pruebas y empaquetado automático) y despliegue continuo.", example: "Flujo que valida cada commit con tests y despliega en Kubernetes.", uso: "Pilar de la cultura DevOps." },
  { num: 146, term: "Cliente (en cliente-servidor)", def: "Dispositivo, aplicación o proceso que inicia la comunicación solicitando servicios, recursos o datos a un servidor.", example: "El navegador Chrome o una app móvil.", uso: "Gestión de la interfaz de usuario." },
  { num: 147, term: "Cloud native", def: "Enfoque para diseñar, construir y operar aplicaciones pensadas para aprovechar las ventajas del modelo en la nube.", example: "Microservicios contenerizados con Docker, orquestados en Kubernetes.", uso: "Adherencia a los principios de 12-Factor App." },
  { num: 148, term: "Código espagueti", def: "Antipatrón que describe un código fuente desordenado, con flujo de control enredado y carente de arquitectura.", example: "Un único archivo de 5.000 líneas con múltiples saltos goto.", uso: "Causa principal de bugs recurrentes." },
  { num: 149, term: "Código limpio (clean code)", def: "Código fuente escrito con simplicidad, claridad y elegancia, fácil de leer, entender, probar y mantener.", example: "Funciones con una sola responsabilidad, nombres autoexplicativos.", uso: "Aplicación de principios SOLID, DRY, KISS." },
  { num: 150, term: "Código muerto (dead code)", def: "Sección de código fuente que nunca se ejecuta o cuyo resultado nunca se utiliza.", example: "Una función de cálculo de impuestos que quedó en desuso.", uso: "Identificado por herramientas de análisis estático." },
  { num: 151, term: "Concurrencia", def: "Capacidad de un sistema de gestionar la ejecución de múltiples tareas en periodos de tiempo superpuestos.", example: "Un servidor web procesando cientos de peticiones concurrentes mediante un bucle de eventos.", uso: "Mediante hilos, corrutinas o modelos de actores." },
  { num: 152, term: "Configuración", def: "Conjunto de parámetros y variables externas que definen el comportamiento de una aplicación sin requerir modificar su código fuente.", example: "La cadena de conexión DATABASE_URL en un archivo .env.", uso: "Separación código/configuración siguiendo 12-Factor App." },
  { num: 153, term: "Consola", def: "Interfaz de texto plano (CLI) que permite a los usuarios interactuar con el sistema operativo o aplicaciones mediante comandos.", example: "La terminal de Linux o la consola de Chrome DevTools.", uso: "Acceso a bajo nivel para administración de servidores." },
  { num: 154, term: "Contenedorización", def: "Forma de virtualización que empaqueta una aplicación y todas sus dependencias en un contenedor aislado.", example: "Crear una imagen Docker con una app Node.js.", uso: "Utiliza namespaces y cgroups del kernel de Linux." },
  { num: 155, term: "Control de versiones distribuido", def: "Sistema de control de versiones donde cada clon del repositorio contiene el historial completo.", example: "Git o Mercurial.", uso: "Mayor resiliencia ante caídas del servidor central." },
  { num: 156, term: "Credenciales", def: "Datos confidenciales de identificación y autenticación (contraseñas, claves SSH, tokens API) para validar el acceso.", example: "AWS_ACCESS_KEY_ID y AWS_SECRET_ACCESS_KEY.", uso: "Almacenamiento seguro en gestores de secretos." },
  { num: 157, term: "Criterio de aceptación", def: "Lista explícita y verificable de condiciones que una funcionalidad debe cumplir para ser aprobada.", example: "\"El usuario debe recibir un correo de confirmación en menos de 60 segundos\".", uso: "Base para pruebas de aceptación automatizadas." },
  { num: 158, term: "Cron job (tarea programada)", def: "Proceso configurado para ejecutarse de forma automática y recurrente en momentos o intervalos específicos.", example: "Script con 0 3 * * * para ejecutar copia de seguridad a las 3 AM.", uso: "Tareas de mantenimiento y sincronizaciones periódicas." },
  { num: 159, term: "Data warehouse", def: "Repositorio centralizado de datos diseñado específicamente para el análisis y generación de informes a gran escala.", example: "Años de transacciones en Google BigQuery para análisis de negocio.", uso: "Optimizado para cargas analíticas (OLAP)." },
  { num: 160, term: "Database schema (esquema de base de datos)", def: "Estructura formal que define la organización lógica de una base de datos: tablas, columnas, tipos de datos, relaciones e índices.", example: "Definición DDL con tablas usuarios y pedidos con clave foránea.", uso: "Garantiza la integridad referencial." },
  { num: 161, term: "Debug (depurar)", def: "Actividad metódica de encontrar, analizar y resolver anomalías, cuellos de botella o fallos en el código fuente.", example: "Ejecutar step over en VS Code para ver en qué punto una variable toma el valor null.", uso: "Herramientas de instrumentación de código." },
  { num: 162, term: "Despliegue continuo", def: "Práctica donde cada cambio que supera las pruebas automatizadas se publica directamente a producción sin intervención manual.", example: "Hacer un commit en main y ver cómo el pipeline lo despliega en 7 minutos.", uso: "Requiere cobertura de pruebas exhaustiva." },
  { num: 163, term: "Desarrollo ágil", def: "Enfoque iterativo e incremental para la gestión de proyectos centrado en la colaboración continua y entregas tempranas.", example: "Un equipo multidisciplinar organizando el trabajo en sprints de dos semanas.", uso: "Aplicación de marcos como Scrum o Kanban." },
  { num: 164, term: "Diagrama de flujo", def: "Representación gráfica de la secuencia de pasos lógicos, decisiones y bifurcaciones que integran un algoritmo o proceso.", example: "Diagrama para restablecer contraseña: pedir email → ¿existe usuario? → enviar token.", uso: "Modelado visual para validar lógica con stakeholders." },
  { num: 165, term: "Diagrama de clases", def: "Diagrama estructural de UML que muestra las clases del sistema, sus atributos, métodos y las relaciones entre ellas.", example: "Un diagrama UML con las clases Factura, LineaFactura y Cliente.", uso: "Diseño orientado a objetos." },
  { num: 166, term: "Docker", def: "Plataforma de código abierto que automatiza el despliegue de aplicaciones dentro de contenedores de software portables y ligeros.", example: "Un archivo Dockerfile que define cómo compilar una app Python.", uso: "Estandarización de entornos eliminando \"en mi máquina sí funciona\"." },
  { num: 167, term: "Documentación técnica", def: "Material escrito que explica la arquitectura interna, diseño de bases de datos, APIs y directrices de desarrollo para ingenieros.", example: "Un documento en Notion que explica el flujo de autenticación.", uso: "Mantenibilidad del software." },
  { num: 168, term: "Documentación de usuario", def: "Guías, manuales, FAQs y tutoriales orientados a enseñar a los usuarios finales cómo utilizar la aplicación.", example: "El centro de ayuda de una app web que explica cómo exportar informes.", uso: "Reducción de tickets de soporte técnico." },
  { num: 169, term: "Dominio (en desarrollo de software)", def: "Esfera o área de conocimiento del negocio real para la cual se está construyendo el sistema.", example: "En el dominio de la logística: almacenes, rutas, paquetes y flotas.", uso: "Base del Domain-Driven Design (DDD)." },
  { num: 170, term: "End-to-end testing (E2E)", def: "Prueba automatizada que valida el flujo completo de una aplicación desde la perspectiva del usuario final.", example: "Un script en Playwright que abre un navegador real y completa una compra.", uso: "Máxima garantía de funcionamiento global." },
  { num: 171, term: "Entorno de staging", def: "Entorno pre-productivo que replica la infraestructura y configuración del entorno de producción.", example: "Un clúster donde se despliegan versiones candidatas para que QA haga pruebas.", uso: "Validación de migraciones sin riesgo para usuarios reales." },
  { num: 172, term: "Entregable", def: "Resultado tangible, medible y verificado producido como parte de un proyecto de software.", example: "La versión compilada de una app móvil o un documento de arquitectura.", uso: "Hito de control en la gestión de proyectos." },
  { num: 173, term: "Especificación", def: "Documento formal y técnico que describe con precisión los requisitos, comportamiento y diseño de un sistema.", example: "La especificación de ECMAScript que detalla cómo deben comportarse los métodos de JavaScript.", uso: "Guía canónica para desarrolladores." },
  { num: 174, term: "Event loop (bucle de eventos)", def: "Mecanismo central en arquitecturas asíncronas que monitorea continuamente la pila de llamadas y despacha tareas en cola.", example: "El Event Loop de Node.js que permite atender miles de conexiones simultáneas.", uso: "Habilita el modelo de I/O no bloqueante." },
  { num: 175, term: "Evento", def: "Acción, suceso o cambio de estado significativo reconocido por el software que puede ser capturado y procesado.", example: "Un usuario haciendo clic en un botón (click) o la llegada de un mensaje a una cola.", uso: "Núcleo de las arquitecturas Event-Driven." },
  { num: 176, term: "Extensión (plugin, add-on)", def: "Componente modular que añade capacidades específicas a un programa base existente sin modificar su código núcleo.", example: "La extensión GitLens para VS Code.", uso: "Implementación basada en arquitecturas de plugins." },
  { num: 177, term: "Feature (funcionalidad)", def: "Característica distintiva o capacidad concreta de un software que aporta valor directo al usuario.", example: "La posibilidad de iniciar sesión con huella dactilar.", uso: "Desarrollada en ramas de Git aisladas y controlada mediante Feature Flags." },
  { num: 178, term: "Feedback de usuario", def: "Información cuantitativa y cualitativa aportada por los usuarios sobre su experiencia y problemas.", example: "Reseñas en la App Store indicando que el botón de pago no es visible en pantallas pequeñas.", uso: "Entrada crucial para la priorización del Backlog." },
  { num: 179, term: "File system (sistema de archivos)", def: "Mecanismo del sistema operativo que estructura el almacenamiento, nombrado y recuperación de archivos.", example: "La jerarquía /var/log/nginx/access.log en Linux.", uso: "Abstracción mediante llamadas al sistema." },
  { num: 180, term: "Firmware", def: "Programa de software de bajo nivel grabado en la memoria no volátil de un hardware para controlar sus circuitos.", example: "La BIOS o UEFI de una placa base.", uso: "Interfaz directa entre la electrónica física y los sistemas operativos." },
  { num: 181, term: "Fork (bifurcación)", def: "Creación de una copia independiente de un proyecto de código fuente para iniciar un desarrollo paralelo y autónomo.", example: "MariaDB surgió como fork de MySQL.", uso: "Mecanismo base para contribuciones mediante Pull Requests." },
  { num: 182, term: "Frontend framework", def: "Plataforma de software que provee componentes, enrutamiento y gestión de estado para construir interfaces web ricas.", example: "React, Vue.js, Svelte o Angular.", uso: "Virtual DOM o compilación reactiva para minimizar repintados." },
  { num: 183, term: "Functional testing (pruebas funcionales)", def: "Pruebas de caja negra que validan que el software cumple con las funciones especificadas.", example: "Comprobar que al introducir un código postal válido se calcula el coste de envío.", uso: "Verificación de especificaciones de negocio." },
  { num: 184, term: "Gateway (puerta de enlace)", def: "Servidor o nodo de red que actúa como único punto de entrada a un sistema, intermediando y securizando el tráfico.", example: "Kong o AWS API Gateway.", uso: "Centralización de autenticación, SSL, rate limiting y balanceo de carga." },
  { num: 185, term: "Git flow", def: "Modelo de gestión de ramas en Git que organiza el desarrollo en ramas específicas (main, develop, feature, release, hotfix).", example: "Crear rama hotfix/1.2.1 desde main para solucionar un fallo urgente.", uso: "Proyectos con ciclos de lanzamiento programados." },
  { num: 186, term: "GUI (Graphical User Interface)", def: "Interfaz gráfica que permite interactuar con dispositivos electrónicos mediante elementos visuales como ventanas, botones e iconos.", example: "El escritorio de Windows o la interfaz de Spotify.", uso: "Procesamiento de bucles de eventos gráficos." },
  { num: 187, term: "Hardening", def: "Proceso sistemático de refuerzo de la seguridad de un servidor o aplicación reduciendo su superficie de vulnerabilidad.", example: "Cerrar puertos innecesarios y deshabilitar el acceso root por SSH.", uso: "Aplicación de directrices CIS Benchmarks." },
  { num: 188, term: "Hash", def: "Resultado alfanumérico de longitud fija generado por una función matemática determinista e irreversible.", example: "Aplicar SHA-256 a \"password\" genera un hash hexadecimal.", uso: "Almacenamiento seguro de contraseñas con bcrypt o Argon2." },
  { num: 189, term: "Header (cabecera)", def: "Bloque de metadatos situado al inicio de una petición HTTP, paquete de red o archivo que describe su contenido.", example: "Content-Type: application/json o Authorization: Bearer <token>.", uso: "Negociación de contenido y seguridad CORS." },
  { num: 190, term: "Health check (comprobación de estado)", def: "Endpoint o sondeo periódico que verifica si una instancia está operativa y lista para recibir tráfico.", example: "GET /healthz que responde 200 OK si la base de datos está conectada.", uso: "Utilizado por balanceadores de carga y Kubernetes." },
  { num: 191, term: "High availability (alta disponibilidad)", def: "Característica de diseño que asegura un porcentaje de operatividad continuo superior al 99.9%.", example: "Arquitectura multi-zona con servidores redundantes.", uso: "Eliminación de puntos únicos de fallo (SPOF)." },
  { num: 192, term: "Hotfix", def: "Parche urgente de código desarrollado y desplegado de forma inmediata para solucionar un fallo crítico en producción.", example: "Corregir un error que impide procesar pagos.", uso: "Flujo de trabajo abreviado que bifurca desde la rama de producción." },
  { num: 193, term: "Identificador (ID)", def: "Valor único (numérico o alfanumérico) asignado a una entidad para distinguirla inequívocamente de las demás.", example: "Un UUID v4 para identificar una transacción financiera.", uso: "Clave primaria en bases de datos relacionales." },
  { num: 194, term: "Immutable infrastructure (infraestructura inmutable)", def: "Enfoque donde los servidores nunca se modifican en vivo; cualquier cambio implica desplegar una nueva instancia.", example: "Desplegar una nueva imagen AMI en AWS en lugar de conectarse por SSH.", uso: "Prevención de configuration drift." },
  { num: 195, term: "Index (índice de base de datos)", def: "Estructura de datos auxiliar que acelera la velocidad de consulta y recuperación de filas en una tabla.", example: "Un índice sobre la columna email en la tabla usuarios.", uso: "Reduce la búsqueda de O(n) a O(log n)." },
  { num: 196, term: "Inyección de dependencias", def: "Patrón de diseño donde un objeto recibe sus dependencias desde el exterior en lugar de instanciarlas internamente.", example: "Pasar EmailService en el constructor de UserService.", uso: "Desacoplamiento de componentes." },
  { num: 197, term: "Input (entrada)", def: "Conjunto de datos o señales suministradas a un programa o sistema desde una fuente externa.", example: "El texto introducido por un usuario en un formulario de búsqueda.", uso: "Debe considerarse siempre potencialmente no confiable." },
  { num: 198, term: "Integración de sistemas", def: "Proceso técnico de conectar diferentes sistemas informáticos para que funcionen juntos de forma coordinada.", example: "Conectar e-commerce con ERP contable y empresa de mensajería.", uso: "Arquitecturas SOA, pipelines de mensajería asíncrona." },
  { num: 199, term: "Interfaz de línea de comandos (CLI)", def: "Mecanismo de interacción basado puramente en texto donde los usuarios introducen comandos escritos.", example: "La herramienta git, docker o la CLI de AWS.", uso: "Automatización de flujos de trabajo mediante scripts." },
  { num: 200, term: "Interfaz gráfica de usuario (GUI)", def: "Entorno visual compuesto por ventanas, botones, menús y elementos gráficos que facilitan el uso del software.", example: "El panel de administración de WordPress.", uso: "Abstracción intuitiva de operaciones complejas." },
  { num: 201, term: "Intérprete", def: "Programa informático que ejecuta directamente instrucciones en un lenguaje sin necesidad de compilación previa.", example: "El ejecutable python procesando un archivo .py.", uso: "Facilita el desarrollo interactivo (REPL) y la portabilidad." },
  { num: 202, term: "Inventario de software", def: "Registro exhaustivo y actualizado de todos los paquetes, dependencias, versiones y licencias utilizadas en un proyecto.", example: "Un SBOM que lista 120 librerías en una aplicación de banca.", uso: "Gestión de vulnerabilidades conocidas (CVEs)." },
  { num: 203, term: "Lanzamiento (release)", def: "Distribución oficial y formal de una versión específica de un producto de software.", example: "El lanzamiento de v2.0.0 en Google Play.", uso: "Acompañado de Release Notes y etiquetas en Git." },
  { num: 204, term: "Latencia", def: "Tiempo que tarda un paquete de datos o una petición en viajar desde su origen hasta su destino a través de la red.", example: "Una latencia de 35 ms entre Madrid y un servidor en Frankfurt.", uso: "Reducida mediante CDN y Edge Computing." },
  { num: 205, term: "Librería estándar", def: "Colección integral de módulos y utilidades distribuidas por defecto junto con el propio lenguaje de programación.", example: "Los módulos math, os, json y datetime de Python.", uso: "Soluciones probadas sin necesidad de instalar dependencias." },
  { num: 206, term: "Línea de base (baseline)", def: "Estado de referencia documentado que sirve como punto de partida para futuras comparaciones.", example: "Registrar que la app consume 200 MB de RAM y responde en 120 ms antes de una refactorización.", uso: "Evaluación objetiva del impacto de cambios." },
  { num: 207, term: "Load testing (pruebas de carga)", def: "Pruebas que someten a un sistema a una demanda simulada y creciente para evaluar su comportamiento y límites.", example: "Simular 10.000 usuarios concurrentes con k6 o Apache JMeter.", uso: "Identificación de cuellos de botella en bases de datos." },
  { num: 208, term: "Logging (registro de eventos)", def: "Práctica sistemática de registrar eventos, mensajes de depuración, errores y métricas operativas generadas por una aplicación.", example: "[INFO] Usuario id=45 autenticado con éxito desde IP 192.168.1.1.", uso: "Esencial para la observabilidad." },
  { num: 209, term: "Machine Learning (aprendizaje automático)", def: "Rama de la IA que desarrolla algoritmos capaces de aprender patrones a partir de datos para realizar predicciones o decisiones.", example: "Un modelo entrenado para clasificar transacciones como legítimas o fraudulentas.", uso: "Uso de PyTorch, TensorFlow o Scikit-Learn." },
  { num: 210, term: "Main (principal)", def: "Nombre asignado a la rama de código principal en un repositorio Git, o a la función de punto de entrada en varios lenguajes.", example: "public static void main(String[] args) en Java.", uso: "Representa el código probado y listo para producción." },
  { num: 211, term: "Mantenimiento correctivo", def: "Intervenciones técnicas para reparar bugs y fallos detectados en el software en producción.", example: "Corregir una fuga de memoria que hace que el servidor se reinicie cada 12 horas.", uso: "Guiado por informes de incidentes." },
  { num: 212, term: "Mantenimiento evolutivo", def: "Modificaciones continuas para incorporar nuevas funcionalidades, mejoras o adaptaciones a nuevos requerimientos.", example: "Añadir soporte para pagos con Bizum y Apple Pay en una tienda online.", uso: "Representa la mayor parte del ciclo de vida del software." },
  { num: 213, term: "Mantenimiento preventivo", def: "Actividades técnicas planificadas para mejorar la estructura interna, actualizar dependencias y prevenir problemas futuros.", example: "Actualizar Node.js a la última versión LTS y refactorizar módulos obsoletos.", uso: "Reducción activa de la deuda técnica." },
  { num: 214, term: "Mapa de ruta (roadmap)", def: "Documento estratégico y visual que resume la visión, prioridades y evolución planificada de un producto a lo largo del tiempo.", example: "Un roadmap trimestral que detalla qué funcionalidades desarrollar en Q1, Q2 y Q3.", uso: "Comunicación estratégica entre equipo técnico y negocio." },
  { num: 215, term: "Memoria caché", def: "Memoria de acceso ultrarrápido (hardware como L1/L2/L3 o software como Redis) para guardar datos temporales de uso frecuente.", example: "Cachear la lista de productos más vendidos en RAM para evitar 500 consultas SQL/segundo.", uso: "Reducción de latencia." },
  { num: 216, term: "Memoria dinámica", def: "Región de memoria (Heap) que se asigna y libera bajo demanda durante la ejecución del programa.", example: "Crear una lista cuyo tamaño crece a medida que el usuario añade elementos.", uso: "Asignación manual (malloc/free en C) o automática mediante GC." },
  { num: 217, term: "Memoria estática", def: "Región de memoria asignada de forma fija en tiempo de compilación cuyo tamaño permanece constante.", example: "Las variables globales y constantes del programa en el segmento de datos.", uso: "Acceso extremadamente rápido y predecible." },
  { num: 218, term: "Metadatos", def: "Conjunto de datos estructurados que describen las características, formato, origen y propiedades de otros datos.", example: "La fecha de creación, tamaño, autor y permisos de un archivo.", uso: "Indispensables en APIs, cabeceras HTTP y catálogos." },
  { num: 219, term: "Metodología ágil", def: "Filosofía de gestión y desarrollo de software basada en iteraciones cortas, retroalimentación constante y entrega continua de valor.", example: "El marco Scrum con Daily, Sprint Planning, Review y Retrospectiva.", uso: "Adaptación rápida a cambios imprevistos." },
  { num: 220, term: "Microservicio", def: "Servicio individual y autónomo que ejecuta un proceso único de negocio y expone interfaces bien definidas para comunicarse en red.", example: "Un servicio de notificaciones que envía correos y SMS.", uso: "Base de datos propia y ciclo de vida de despliegue independiente." },
  { num: 221, term: "Middleware", def: "Capa de software intermedia que intercepta y procesa las peticiones y respuestas entre el cliente y el controlador final.", example: "Un middleware en Express.js que verifica el token JWT.", uso: "Logging, autenticación, compresión y manejo de errores." },
  { num: 222, term: "Migración de datos", def: "Proceso de selección, extracción, transformación y transferencia de datos desde un sistema o formato de almacenamiento a otro.", example: "Mover 10 millones de registros de Oracle a PostgreSQL en AWS.", uso: "Requiere validación estricta de esquemas." },
  { num: 223, term: "Migración de base de datos", def: "Archivo de código o script SQL versionado que define un cambio estructural incremental en el esquema de la base de datos.", example: "20260831_add_telefono_to_usuarios.sql.", uso: "Reproducir y sincronizar el mismo esquema en todos los entornos." },
  { num: 224, term: "Mock (simulación)", def: "Objeto simulado programable que imita el comportamiento de un componente real en pruebas automatizadas.", example: "Un mock del servicio de SMS que simula una respuesta exitosa sin enviar mensajes reales.", uso: "Aislar la unidad de código de factores externos." },
  { num: 225, term: "Modelo de datos", def: "Representación abstracta y formal que describe cómo se estructuran, relacionan y almacenan los datos dentro de un sistema.", example: "Un modelo ER que define que un Cliente puede tener muchos Pedidos.", uso: "Base para el diseño eficiente de esquemas de bases de datos." },
  { num: 226, term: "Monitoreo (monitoring)", def: "Recolección, análisis y visualización continua en tiempo real de métricas sobre el estado y rendimiento de un sistema.", example: "Un panel de Grafana mostrando uso de CPU, memoria y errores 5xx.", uso: "Configuración de alertas automáticas." },
  { num: 227, term: "Monorepo", def: "Estrategia donde el código fuente de múltiples proyectos, servicios y aplicaciones se aloja en un único repositorio de Git.", example: "Un repositorio que contiene la app móvil, frontend web, backend y librerías compartidas.", uso: "Facilita la reutilización de código." },
  { num: 228, term: "Multihilo (multithreading)", def: "Técnica que permite a un programa ejecutar concurrentemente múltiples hilos dentro del mismo proceso.", example: "Un conversor de vídeo que procesa diferentes fragmentos simultáneamente.", uso: "Maximiza el aprovechamiento del hardware multinúcleo." },
  { num: 229, term: "Multiplataforma", def: "Atributo de un software que le permite compilarse y ejecutarse en múltiples sistemas operativos o dispositivos distintos.", example: "Flutter que permite escribir código una sola vez para iOS, Android y Web.", uso: "Reduce drásticamente los costes de desarrollo." },
  { num: 230, term: "Namespace (espacio de nombres)", def: "Contenedor abstracto que agrupa identificadores bajo un nombre único para evitar colisiones y ambigüedades.", example: "System.IO y System.Net en .NET.", uso: "Organización lógica y modular de librerías complejas." },
  { num: 231, term: "Native app (aplicación nativa)", def: "Aplicación desarrollada específicamente para un sistema operativo concreto utilizando los lenguajes y SDKs oficiales.", example: "Una aplicación iOS desarrollada en Swift con Xcode.", uso: "Máximo rendimiento y acceso directo a todas las APIs de hardware." },
  { num: 232, term: "Network (red)", def: "Infraestructura de hardware y software compuesta por dispositivos interconectados que comparten información.", example: "La red interna (VPC) de una empresa en AWS.", uso: "Configuración de subredes, firewalls y políticas de seguridad." },
  { num: 233, term: "Nodo", def: "Punto individual de conexión, cómputo o almacenamiento dentro de una red o estructura de datos jerárquica.", example: "Un servidor individual dentro de un clúster de Kubernetes, o un elemento en un árbol binario.", uso: "Unidad básica de cómputo en sistemas distribuidos." },
  { num: 234, term: "NoSQL", def: "Categoría de sistemas de gestión de bases de datos que no utilizan el modelo relacional tradicional ni SQL estándar.", example: "MongoDB (documental), Redis (clave-valor), Apache Cassandra (columnar).", uso: "Esquemas flexibles y escalabilidad horizontal masiva." },
  { num: 235, term: "Notificación push", def: "Mensaje instantáneo enviado desde un servidor a un dispositivo de usuario sin requerir una petición previa.", example: "El aviso en la pantalla de bloqueo \"Tu pedido ha salido del restaurante\".", uso: "Implementado mediante FCM de Google o APNs de Apple." },
  { num: 236, term: "Nube híbrida", def: "Entorno que combina infraestructura de nube privada con servicios de nube pública, comunicados de forma segura.", example: "Datos médicos en servidores propios, análisis en AWS.", uso: "Cumplimiento de regulaciones de soberanía de datos." },
  { num: 237, term: "Nube privada", def: "Infraestructura de computación dedicada exclusivamente al uso de una única organización, gestionada interna o externamente.", example: "Un clúster de servidores OpenStack dentro del centro de datos de una entidad gubernamental.", uso: "Máximo control sobre seguridad y configuración." },
  { num: 238, term: "Nube pública", def: "Modelo donde los recursos informáticos son propiedad de un proveedor externo y se ofrecen compartidos por suscripción.", example: "Amazon Web Services (AWS), Microsoft Azure o Google Cloud Platform.", uso: "Despliegue global instantáneo y alta elasticidad." },
  { num: 239, term: "Objetivo de rendimiento", def: "Meta técnica cuantificable y acordada formalmente sobre la velocidad, tiempos de respuesta o consumo de recursos.", example: "\"El 99% de las peticiones deben responder en menos de 150 ms bajo 2.000 req/s\".", uso: "Formalizado en SLA y SLO." },
  { num: 240, term: "Observabilidad", def: "Medida de la capacidad de inferir los estados internos de un sistema complejo basándose en sus salidas externas.", example: "Usar trazas distribuidas para identificar qué microservicio causó un retraso de 3 segundos.", uso: "Basada en Métricas, Logs y Trazas distribuidas." },
  { num: 241, term: "Onboarding (incorporación)", def: "Proceso guiado para integrar y familiarizar rápidamente a un nuevo desarrollador con la base de código o a un usuario con una app.", example: "Una guía técnica con scripts que permite al nuevo programador tener el proyecto funcionando el primer día.", uso: "Estandarización de entornos mediante Devcontainers." },
  { num: 242, term: "Open API (API abierta)", def: "Interfaz de programación documentada públicamente que permite a desarrolladores externos acceder a los datos o servicios de una plataforma.", example: "La API abierta del servicio meteorológico nacional.", uso: "Especificación mediante el estándar OpenAPI Specification (OAS)." },
  { num: 243, term: "Orquestación", def: "Coordinación y gestión automatizada del ciclo de vida de múltiples contenedores, servicios o flujos de trabajo complejos.", example: "Kubernetes gestionando el despliegue, autoescalado y autorreparación de 500 microservicios.", uso: "Eliminación de la administración manual." },
  { num: 244, term: "Output (salida)", def: "Información, datos, archivos o señales que un programa genera y entrega al exterior tras procesar las entradas.", example: "El archivo PDF de una factura generado tras completar una compra.", uso: "Formateado según contratos de interfaz." },
  { num: 245, term: "Overhead (sobrecarga)", def: "Tiempo de computación, memoria o ancho de banda adicional consumido por una capa de abstracción o proceso auxiliar.", example: "El tiempo extra de una llamada que pasa por tres capas intermedias de middleware.", uso: "Métrica a vigilar en sistemas de alto rendimiento." },
  { num: 246, term: "Pair programming (programación en pareja)", def: "Técnica donde dos programadores trabajan juntos en la misma estación de trabajo sobre el mismo código.", example: "Un desarrollador como \"conductor\" (escribiendo) y otro como \"navegante\" (revisando estrategia).", uso: "Incremento de la calidad del código." },
  { num: 247, term: "Paradigma de programación", def: "Enfoque, estilo o filosofía fundamental que define cómo se estructura, organiza y conceptualiza la ejecución de un programa.", example: "POO, Programación Funcional, Imperativa o Declarativa.", uso: "Guía el diseño arquitectónico y las abstracciones." },
  { num: 248, term: "Performance (rendimiento)", def: "Medida de la eficiencia con la que un software ejecuta sus tareas, evaluada en tiempo de respuesta, throughput y uso de recursos.", example: "Optimizar una función de 4 segundos a 20 milisegundos.", uso: "Analizado mediante profiling y benchmarking." },
  { num: 249, term: "Persistencia", def: "Capacidad de los datos de un programa de sobrevivir al fin del proceso que los creó, almacenándose en soportes no volátiles.", example: "Guardar datos de un usuario en un disco SSD mediante PostgreSQL.", uso: "Implementada mediante bases de datos, ORMs y sistemas de archivos." },
  { num: 250, term: "Pipeline de CI/CD", def: "Flujo de trabajo secuencial y automatizado que toma el código fuente y lo pasa por etapas de compilación, análisis, pruebas y despliegue.", example: "Lint → Tests → Build Docker → Tests E2E → Despliegue en Producción.", uso: "Garantiza que ningún código llegue a producción sin controles de calidad." },
  { num: 251, term: "Plataforma", def: "Entorno tecnológico de hardware y software subyacente sobre el cual se diseñan, ejecutan y operan aplicaciones y servicios.", example: "Node.js como plataforma de ejecución, o iOS como plataforma móvil.", uso: "Proporciona las APIs de bajo nivel y runtime necesarios." },
  { num: 252, term: "Plugin (complemento)", def: "Módulo de software independiente que se acopla a un programa principal para extender o personalizar sus funcionalidades.", example: "Un plugin de pasarela de pago de Stripe en WooCommerce.", uso: "Basado en el Principio de Abierto/Cerrado." },
  { num: 253, term: "Portabilidad", def: "Atributo de calidad del software que mide la facilidad con la que un programa puede trasladarse y ejecutarse en diferentes entornos técnicos.", example: "Una aplicación Java que se ejecuta en Windows, Linux y macOS gracias a la JVM.", uso: "Maximizada mediante contenerización con Docker." },
  { num: 254, term: "Postman", def: "Plataforma de software líder utilizada para diseñar, probar, documentar y simular peticiones a APIs HTTP/REST.", example: "Crear una colección de peticiones para probar los endpoints de autenticación.", uso: "Automatización de pruebas de integración de APIs." },
  { num: 255, term: "Producción", def: "Entorno final donde el software opera en vivo, procesando datos reales y atendiendo a los usuarios finales.", example: "Los clústeres de servidores al que se conectan los clientes al entrar en www.miempresa.com.", uso: "Máxima exigencia de estabilidad." },
  { num: 256, term: "Profiling (perfilado)", def: "Análisis dinámico de un programa en ejecución para medir con exactitud el consumo de memoria, tiempo en CPU y frecuencia de llamada.", example: "Usar cProfile en Python para descubrir que el 85% del tiempo se gasta en serialización.", uso: "Identificación precisa de cuellos de botella." },
  { num: 257, term: "Programación funcional", def: "Paradigma declarativo que estructura el código como la evaluación de funciones matemáticas puras evitando el estado mutable.", example: "Usar map, filter y reduce sobre listas inmutables en lugar de bucles for.", uso: "Facilita la concurrencia y el paralelismo." },
  { num: 258, term: "Programación imperativa", def: "Paradigma donde el desarrollador describe detalladamente la secuencia exacta de instrucciones y cambios de estado.", example: "Inicializar un contador a cero, iterar con for e ir acumulando valores.", uso: "Enfoque directo y cercano a la arquitectura de hardware." },
  { num: 259, term: "Progreso (progress)", def: "Representación visual o métrica del porcentaje completado de una tarea computacional asíncrona o de larga duración.", example: "Una barra de carga que indica que la subida de un vídeo va por el 67%.", uso: "Crucial para la UX; comunicado vía WebSockets o SSE." },
  { num: 260, term: "Prompt", def: "Texto, instrucción o contexto estructurado suministrado como entrada a un modelo de IA para guiar su respuesta generativa.", example: "\"Actúa como un experto en ciberseguridad y audita esta función Python\".", uso: "Ingeniería de prompts aplicando técnicas como Few-Shot y Chain-of-Thought." },
  { num: 261, term: "Protocolo de transferencia de archivos (FTP)", def: "Protocolo de red cliente-servidor diseñado para transferir archivos entre sistemas conectados a una red TCP/IP.", example: "Conectarse mediante FileZilla para subir archivos HTML a un servidor de alojamiento.", uso: "En entornos modernos se sustituye por SFTP." },
  { num: 262, term: "Prototipo rápido (rapid prototyping)", def: "Metodología de creación ágil de versiones preliminares e interactivas para validar conceptos y flujos con usuarios reales.", example: "Crear una maqueta navegable en Figma en 48 horas.", uso: "Minimización del riesgo de desarrollo." },
  { num: 263, term: "Proxy", def: "Servidor o aplicación intermedia que actúa como intermediario en las solicitudes enviadas por un cliente a otro servidor.", example: "Un proxy inverso Nginx que recibe el tráfico y lo redirige a múltiples instancias backend.", uso: "Terminación SSL, balanceo de carga y filtrado de seguridad." },
  { num: 264, term: "Pull request (solicitud de extracción)", def: "Propuesta formal para fusionar un conjunto de cambios realizados en una rama de Git hacia la rama principal, abriendo un espacio de revisión.", example: "PR en GitHub titulado \"Añadir autenticación con Google OAuth\".", uso: "Punto central del control de calidad." },
  { num: 265, term: "Punto de restauración", def: "Copia de seguridad o captura del estado íntegro de un sistema o base de datos en un instante específico para permitir su recuperación.", example: "Una snapshot de la base de datos tomada antes de ejecutar una migración compleja.", uso: "Esencial en planes de recuperación ante desastres." },
  { num: 266, term: "Query language (lenguaje de consultas)", def: "Lenguaje especializado para realizar consultas, búsquedas y modificaciones de datos en motores de bases de datos.", example: "SQL para relacionales, GraphQL para APIs o Cypher para grafos.", uso: "Abstracción declarativa que permite especificar qué datos se necesitan." },
  { num: 267, term: "Queue (cola)", def: "Estructura de datos lineal que sigue el principio FIFO (First In, First Out).", example: "Una cola de mensajes en RabbitMQ con correos electrónicos pendientes de envío.", uso: "Desacoplamiento de procesos asíncronos y absorción de picos de tráfico." },
  { num: 268, term: "Rate limiting (límite de tasa)", def: "Técnica que restringe el número máximo de peticiones que un cliente puede realizar a una API en un periodo de tiempo.", example: "Limitar a 60 peticiones por minuto, retornando HTTP 429 si se supera.", uso: "Protección contra ataques DoS y scraping." },
  { num: 269, term: "Refactorización de código", def: "Modificación sistemática de la estructura interna del código para mejorar su legibilidad y modularidad sin cambiar su comportamiento.", example: "Extraer la lógica de cálculo de descuentos en una clase separada con sus propias pruebas.", uso: "Reducción continua de la deuda técnica." },
  { num: 270, term: "Registro de cambios (changelog)", def: "Documento estructurado e histórico que lista cronológicamente todas las novedades, correcciones y cambios en cada versión.", example: "Un archivo CHANGELOG.md con apartados Added, Changed, Fixed.", uso: "Comunicación transparente con usuarios." },
  { num: 271, term: "Registro de errores (error log)", def: "Archivo o flujo donde el software registra los fallos, excepciones no controladas y anomalías en tiempo de ejecución.", example: "Un archivo error.log con el stack trace de un NullPointerException.", uso: "Fuente primaria para el diagnóstico de incidentes." },
  { num: 272, term: "Repositorio remoto", def: "Versión del repositorio alojada en un servidor accesible a través de la red que sirve de punto central de sincronización.", example: "https://github.com/usuario/mi-proyecto.git.", uso: "Permite la colaboración en equipo y disparar flujos CI." },
  { num: 273, term: "Resiliencia", def: "Capacidad de un sistema de anticipar, absorber, recuperarse y seguir funcionando ante la presencia de fallos o caídas parciales.", example: "Una app que si no puede conectar con recomendaciones muestra productos populares por defecto.", uso: "Mediante Circuit Breaker, Retry con Backoff Exponencial." },
  { num: 274, term: "Respuesta (response)", def: "Mensaje devuelto por un servidor a un cliente como contestación a una petición recibida a través de la red.", example: "HTTP 200 OK con un cuerpo JSON con los datos del usuario.", uso: "Estructuración de códigos de estado normalizados." },
  { num: 275, term: "REST API", def: "Interfaz de programación que se adhiere a los principios REST sobre el protocolo HTTP.", example: "API que expone /api/v1/libros con GET, POST, PUT y DELETE.", uso: "Estilo de diseño dominante en la web para integración de servicios." },
  { num: 276, term: "Retorno (return)", def: "Sentencia de programación que finaliza la ejecución de una función y transfiere el control al punto donde fue invocada.", example: "return resultado; al final de una función de cálculo.", uso: "Desapila el marco de la función en la pila de llamadas." },
  { num: 277, term: "Revisión de código (code review)", def: "Proceso formal y colaborativo donde uno o más desarrolladores examinan el código escrito por un compañero antes de fusionarlo.", example: "Dejar comentarios en un PR señalando una condición de carrera.", uso: "Aseguramiento de la calidad y difusión del conocimiento técnico." },
  { num: 278, term: "Rollback (reversión)", def: "Acción de deshacer un conjunto de operaciones o un despliegue completo para restaurar el sistema al último estado estable conocido.", example: "kubectl rollout undo deployment/mi-app para volver a la versión anterior.", uso: "Reduce el MTTR ante incidencias graves." },
  { num: 279, term: "Root (raíz)", def: "Cuenta de usuario con los máximos privilegios administrativos en sistemas Unix/Linux, o el directorio base / de la jerarquía del sistema de archivos.", example: "El usuario root que puede modificar cualquier archivo del sistema operativo.", uso: "Los procesos en producción deben ejecutarse como usuarios no privilegiados." },
  { num: 280, term: "Runtime error (error de ejecución)", def: "Error que ocurre durante la ejecución del programa, después de compilar con éxito, provocando una excepción o terminación abrupta.", example: "Dividir por cero (ZeroDivisionError) o acceder a un puntero nulo (NullReferenceException).", uso: "Mitigado mediante validación de entradas y bloques try-catch." },
  { num: 281, term: "SaaS (Software as a Service)", def: "Modelo de distribución donde una aplicación completa se aloja en la nube y se entrega a usuarios bajo suscripción.", example: "Google Workspace, Slack, Notion o Microsoft 365.", uso: "El proveedor gestiona infraestructura, seguridad y mantenimiento." },
  { num: 282, term: "Scripting", def: "Práctica de escribir programas cortos y enfocados para automatizar tareas repetitivas, procesar datos o coordinar otros programas.", example: "Un script en Python que descarga automáticamente facturas y las organiza por fecha.", uso: "Empleado en administración de sistemas y pipelines de datos." },
  { num: 283, term: "Seguridad informática", def: "Disciplina y conjunto de medidas técnicas y buenas prácticas para proteger sistemas, redes y datos contra accesos no autorizados.", example: "Implementar autenticación multifactor, HTTPS/TLS y análisis de vulnerabilidades.", uso: "Alineación con OWASP Top 10, ISO 27001, NIST." },
  { num: 284, term: "Semáforo (semaphore)", def: "Mecanismo clásico de sincronización que utiliza un contador para controlar el acceso concurrente de múltiples hilos a recursos compartidos.", example: "Un semáforo con contador 5 que permite como máximo 5 hilos consultando la base de datos simultáneamente.", uso: "Primitiva fundamental en programación multihilo." },
  { num: 285, term: "Semántica", def: "Significado lógico y conceptual de las instrucciones, estructuras sintácticas y datos en un lenguaje de programación.", example: "Usar la etiqueta HTML semántica nav en lugar de un div genérico para la navegación.", uso: "Clave para la accesibilidad web y SEO." },
  { num: 286, term: "Servicio", def: "Componente o programa de software independiente que se ejecuta en segundo plano para proporcionar una función específica a otros componentes.", example: "Un servicio de autenticación (auth-service) o sshd que atiende conexiones SSH.", uso: "Bloque fundamental en arquitecturas desacopladas." },
  { num: 287, term: "Servidor de aplicaciones", def: "Servidor o runtime especializado que aloja y ejecuta la lógica de negocio pesada, transacciones y conexiones a bases de datos.", example: "Tomcat o WildFly para aplicaciones Java, o Gunicorn ejecutando Django.", uso: "Se sitúa entre el servidor web y la base de datos." },
  { num: 288, term: "Servidor web", def: "Software o hardware que escucha peticiones HTTP/HTTPS y entrega recursos (páginas HTML, imágenes, datos) a los clientes.", example: "Nginx, Apache HTTP Server o Caddy.", uso: "Optimizado para servir archivos estáticos y como proxy inverso." },
  { num: 289, term: "Sesión", def: "Estado temporal de interacción continua mantenido entre un usuario y un sistema durante un periodo de tiempo determinado.", example: "Mantener al usuario logueado mientras añade productos al carrito a lo largo de 30 minutos.", uso: "Gestión mediante cookies seguras o tokens JWT." },
  { num: 290, term: "Setup (configuración inicial)", def: "Proceso estructurado de preparación, instalación y configuración del entorno necesario para ejecutar un proyecto.", example: "Ejecutar git clone, crear .env, instalar dependencias y correr migraciones.", uso: "Estandarizado en README.md o automatizado mediante Devcontainers." },
  { num: 291, term: "Sistema de gestión de bases de datos (SGBD)", def: "Paquete de software que proporciona las herramientas para definir, crear, consultar y mantener bases de datos estructuradas.", example: "PostgreSQL, MySQL, Microsoft SQL Server, Oracle Database o MongoDB.", uso: "Gestiona transacciones ACID y optimización de consultas." },
  { num: 292, term: "Sistema embebido", def: "Sistema informático de hardware y software dedicado diseñado para realizar una función de control fija dentro de un dispositivo mayor.", example: "El microcontrolador que gestiona los frenos ABS o el software de un reloj inteligente.", uso: "Desarrollado en C, C++ o Rust bajo restricciones de memoria y tiempo real." },
  { num: 293, term: "Sistema distribuido", def: "Conjunto de ordenadores o nodos independientes conectados por red que se coordinan, presentándose como un único sistema.", example: "El clúster de búsqueda de Google procesando consultas entre decenas de miles de servidores.", uso: "Diseñado bajo el Teorema CAP y algoritmos de consenso (Raft, Paxos)." },
  { num: 294, term: "Smoke testing (prueba de humo)", def: "Conjunto preliminar y rápido de pruebas básicas que valida que las funciones más críticas operan correctamente tras un nuevo despliegue.", example: "Comprobar que la página de inicio carga, el login responde y la base de datos está conectada.", uso: "Actúa como primer filtro tras un despliegue." },
  { num: 295, term: "Snapshot (instantánea)", def: "Copia o imagen congelada en el tiempo que captura el estado exacto de un volumen de almacenamiento o base de datos en un instante concreto.", example: "Una snapshot de un disco AWS EBS antes de una actualización crítica.", uso: "Permite restauraciones rápidas." },
  { num: 296, term: "Software de gestión", def: "Categoría de aplicaciones empresariales diseñadas para centralizar, automatizar y coordinar los procesos operativos de una organización.", example: "Un ERP como SAP o un CRM como Salesforce.", uso: "Integración con múltiples bases de datos y flujos de trabajo de aprobación." },
  { num: 297, term: "Solución (solution)", def: "Conjunto estructurado y cohesionado de proyectos de software, librerías, configuraciones y documentación que resuelven integralmente un problema de negocio.", example: "Un archivo .sln en Visual Studio que agrupa la API backend, la biblioteca de dominio y los tests.", uso: "Organización de la arquitectura a nivel de compilación." },
  { num: 298, term: "Source code (código fuente)", def: "Conjunto de líneas de texto legibles por personas escritas en un lenguaje de programación que contienen las instrucciones completas que rigen el comportamiento de un software.", example: "Los archivos .ts, .py o .rs escritos por los programadores.", uso: "Activo intelectual central sometido a control de versiones." },
  { num: 299, term: "Sesión de usuario", def: "Período de tiempo durante el cual un usuario interactúa de forma continua con una aplicación, con seguimiento del estado de la sesión.", example: "El tiempo que un usuario permanece conectado a su cuenta bancaria online antes de que expire la sesión automáticamente.", uso: "Gestión segura mediante tokens de sesión renovables y expiración automática." },
  { num: 300, term: "Sprint", def: "Período de tiempo fijo (generalmente 1 a 4 semanas) dentro de una metodología ágil durante el cual el equipo desarrolla y entrega un incremento de producto.", example: "Un sprint de dos semanas en el que el equipo completa las historias de usuario de la nueva sección de pagos.", uso: "Marco temporal que impone ritmo y foco en el equipo, reduciendo el trabajo en curso (WIP)." },
];